{
  "mechanisms": [
    {
      "name": "outcome_dependent_temperature",
      "title": "Outcome-Dependent Inverse Temperature",
      "description": "The inverse temperature applied to the Q-values changes depending on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "beta_win",
          "bounds": [0, 10]
        },
        {
          "name": "beta_loss",
          "bounds": [0, 10]
        }
      ],
      "evidence": "current_beta = beta_win if prev_reward == 1 else beta_loss\n\n        logits_1 = current_beta * q_stage1\n...\n        logits_2 = current_beta * q_stage2[s_idx]",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "A perseveration parameter is added to the stage-1 logit of the action chosen on the previous trial.",
      "params": [
        {
          "name": "perseveration",
          "bounds": [-3, 3]
        }
      ],
      "evidence": "if prev_a1 != -1:\n            logits_1[prev_a1] += perseveration",
      "expressible_in_slots": true
    },
    {
      "name": "q_init_05",
      "title": "0.5 Q-Value Initialization",
      "description": "Stage-1 and Stage-2 Q-values are initialized to 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1 = np.zeros(2) + 0.5\n    q_stage2 = np.zeros((2, 2)) + 0.5",
      "expressible_in_slots": true
    }
  ]
}
